-- CA_0320_monroe_voting_locations.sql
-- Hand-checked voting locations, used when Google's Voting Information Project (VIP) has none.
-- First county: Monroe County, Indiana, for the November 3, 2026 general election.
--
-- WHY. Monroe assigns each voter one Election Day polling place by precinct (83 precincts,
-- 28 sites) and has one early-voting site for the whole county. Measured 2026-10-22 on 186 real
-- county addresses through /api/essentials/voter-info: every polling place Google returned
-- matched the county's official list (125 of 125), but about a third of lookups returned no
-- location at all, and the same address flipped between an answer and none on retries. Twelve
-- precincts never got an answer in 20 tries each. Reformatting the address never helped.
-- So the endpoint keeps Google first and fills only what Google left empty, from these tables.
-- Rules: backend/src/lib/localVotingLocations.ts. Data and how to re-check it:
-- backend/data/voting-locations/.
--
-- SHAPE. A "set" is one county for one election. Precincts and sites belong to a set, so a
-- redrawn precinct map or a moved site is a new set, never an edit that leaks into the next
-- election. A set is served only through its election_date; after that it is ignored, so stale
-- data shows nothing rather than something wrong.
--
-- ADDITIVE ONLY. Three new tables in essentials; nothing else touched. RLS on with no policy, so
-- only the backend role can read them (same pattern as 1901; watchlist #81).
-- ⚠ ev-cto decision 0006: geometry is SRID 4326 and lookups use ST_Covers / ST_DWithin only.

BEGIN;

CREATE TABLE IF NOT EXISTS essentials.voting_location_sets (
  id            integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  county_fips   text        NOT NULL CHECK (county_fips ~ '^[0-9]{5}$'),
  county_name   text        NOT NULL,
  state         char(2)     NOT NULL,
  election_name text        NOT NULL,
  election_date date        NOT NULL,
  source_label  text        NOT NULL,  -- shown on the card: where these locations came from
  source_url    text        NOT NULL,
  last_checked  date        NOT NULL,  -- shown on the card; bump it on every re-check
  lookup_url    text,                  -- the state's official polling-place lookup
  created_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (county_fips, election_date)
);

CREATE TABLE IF NOT EXISTS essentials.voting_precincts (
  id       integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  set_id   integer NOT NULL REFERENCES essentials.voting_location_sets(id) ON DELETE CASCADE,
  code     text    NOT NULL,  -- the county's own precinct label, e.g. 'PERRY 06'
  geometry geometry(MultiPolygon, 4326) NOT NULL,
  UNIQUE (set_id, code)
);
CREATE INDEX IF NOT EXISTS voting_precincts_geometry_idx ON essentials.voting_precincts USING gist (geometry);

CREATE TABLE IF NOT EXISTS essentials.voting_sites (
  id             integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  set_id         integer NOT NULL REFERENCES essentials.voting_location_sets(id) ON DELETE CASCADE,
  kind           text    NOT NULL CHECK (kind IN ('election_day', 'early_vote')),
  name           text    NOT NULL,
  address        text    NOT NULL,
  lat            double precision,
  lng            double precision,
  hours          text,
  start_date     date,   -- early_vote window
  end_date       date,   -- early_vote window; hidden after this day
  -- election_day: the precincts assigned here. early_vote: empty, open to the whole county.
  precinct_codes text[]  NOT NULL DEFAULT '{}',
  CHECK ((kind = 'election_day') = (cardinality(precinct_codes) > 0))
);
CREATE INDEX IF NOT EXISTS voting_sites_set_id_idx ON essentials.voting_sites (set_id);

ALTER TABLE essentials.voting_location_sets ENABLE ROW LEVEL SECURITY;
ALTER TABLE essentials.voting_precincts     ENABLE ROW LEVEL SECURITY;
ALTER TABLE essentials.voting_sites         ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE essentials.voting_location_sets IS
  'One county x one election of hand-checked voting locations; fallback when Google VIP returns none. Served only through election_date. CA_0320.';

-- ---------------------------------------------------------------------------
-- Data: Monroe County, IN — 2026 general. Sources and SHA-256 of each county PDF are in
-- backend/data/voting-locations/monroe-in-2026-general.json.
-- ---------------------------------------------------------------------------

-- Monroe County, IN — 2026 General Election (2026-11-03)
-- Generated from data/voting-locations/monroe-in-2026-general.json by scripts/generate-voting-locations-migration.mjs.
-- 83 precincts, 28 Election Day sites, 1 early-vote site(s).

DELETE FROM essentials.voting_location_sets WHERE county_fips = '18105' AND election_date = '2026-11-03';  -- cascades to precincts and sites

VALUES ('18105', 'Monroe County', 'IN', '2026 General Election', '2026-11-03', 'Monroe County Election Board — Official 2026 Poll Site Locations', 'https://www.in.gov/counties/monroe/Departments/clerk-of-court/voter-registration/', '2026-10-22', 'https://indianavoters.in.gov/');

Sat, Oct 24: 9 am - 4 pm
Sat, Oct 31: 9 am - 4 pm
Mon, Nov 2: 8 am - 12 pm (noon)', '2026-10-06', '2026-11-02');


DO $$
DECLARE
  sid int := (SELECT id FROM essentials.voting_location_sets WHERE county_fips = '18105' AND election_date = '2026-11-03');
  n_precincts int;
  bad text;
BEGIN
  SELECT count(*) INTO n_precincts FROM essentials.voting_precincts WHERE set_id = sid;
  IF n_precincts <> 83 THEN
    RAISE EXCEPTION 'expected 83 precincts, found %', n_precincts;
  END IF;

  SELECT string_agg(p.code, ', ') INTO bad
    FROM essentials.voting_precincts p
   WHERE p.set_id = sid
     AND (SELECT count(*) FROM essentials.voting_sites s
           WHERE s.set_id = sid AND s.kind = 'election_day' AND p.code = ANY (s.precinct_codes)) <> 1;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'precincts without exactly one Election Day site: %', bad;
  END IF;

  SELECT string_agg(c, ', ') INTO bad
    FROM essentials.voting_sites s, unnest(s.precinct_codes) c
   WHERE s.set_id = sid
     AND NOT EXISTS (SELECT 1 FROM essentials.voting_precincts p WHERE p.set_id = sid AND p.code = c);
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'sites list precincts that do not exist: %', bad;
  END IF;

  SELECT string_agg(code, ', ') INTO bad
    FROM essentials.voting_precincts WHERE set_id = sid AND NOT ST_IsValid(geometry);
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'precincts with invalid geometry after ST_MakeValid: %', bad;
  END IF;
END $$;

COMMIT;
